          "text": "🎉 担当者が4名見つかりました！！ 🎉\n\nこのプロットが表示されたユーザー様限定！\n\nただいま特別対応として――\n\n専任担当者4名が同時接続中！！\n\n━━━━━━━━━━━━━━\n\n✨ 追加料金 ￥0\n\n✨ 登録料 ￥0\n\n✨ 面倒なお手続き不要\n\n✨ 担当者4名による安心サポート！\n\n━━━━━━━━━━━━━━\n\n通常、担当者は1名のみとなっておりますが――\n\n今回はなんと4名！！\n\n『✅ 対象者：ユーザー様』\n\n『⚠️ 担当者情報が重複しています』\n\n『🔎 接続元を照合しています……』\n\n『❌ 一致する管理情報がありません』\n\n『🔄 自動振り分けを再試行しています……』\n\n『❌ 処理に失敗しました』\n\n現在、4名すべての担当者が\n\nユーザー様を自身の担当対象として認識しています。\n\nなお、確認の結果――\n\n4名は同一の会社・組織には所属しておりません。\n\nなぜ別々の担当者が同じ接続先へ集まったのか、\n\n現在も原因は確認できておりません。\n\n……一部表示に乱れがございますが、\n\nご利用には問題ございません！\n\n誰か1名を選択する必要もございません。\n\n気になる担当者とお話しいただくのも、\n\n4名全員をご利用いただくのも自由です！\n\nどうぞお気軽にトークを開始してください。\n\n━━━━━━━━━━━━━━\n\n※担当者間で対応方針が異なる場合がございます。\n\n※担当者同士の応答が競合する場合がございます。\n\n※一部担当者がユーザー様を過度に優先する場合がございます。\n\n※接続解除：現在ご利用いただけません。\n\n※接続情報：縺薙％縺九ｉ\n\n※修正終了条件：菫ｮ豁｣縺ｧ縺阪∪縺帙ｓ\n\n※対象地域：隕∫ｭ峨＠縺ｦ縺上□縺輔＞\n\n※通知状態：遒ｺ隱肴ｸ医∩\n\n『⚠️ 担当者重複状態：継続中』\n\n✅ 個別対応ページ：利用可能\n\n4名それぞれの担当者と、\n\n1対1での個別対応もご利用いただけます。\n\n🔗 ナギ\n\n接続・ご案内担当\n\n▶ 「おめでとうございます！！」個別対応はこちら\n\n🔧 サイ\n\n不具合修正担当\n\n▶ 「申し訳ありません。」個別対応はこちら\n\n🕯️ ヨリ\n\n地域見守り担当\n\n▶ 「〇〇にお住いの方！」個別対応はこちら\n\n📩 ツグ\n\n重要通知担当\n\n▶ 「⚠️重要なお知らせ⚠️」個別対応はこちら\n\n━━━━━━━━━━━━━━\n\n※個別対応ページでは、他の担当者は同時接続されません。\n\n※本ページでは引き続き4名同時対応となります。\n\n『✅ ご利用方法の確認が完了しました』\n\nそれではユーザー様。\n\n4名同時対応をお楽しみください！！",
