          "text": "🦋💖✨ その黒歴史、アタシが消しとくわよ♡ ✨💖🦋\n\n╭━━━━━━━━━━━━━━━━━━━╮\n　✨🗑️ 人生スッキリお片付けサービス 🗑️✨\n╰━━━━━━━━━━━━━━━━━━━╯\n\n💌 このプロットが表示されたユーザーちゃんへ 💌\n\n📸 消したい写真\n💬 見たくないトーク履歴\n📝 残したくないメモ\n💔 思い出したくない黒歴史\n\nそんなもの、ありませんか？\n\n⋆｡ﾟ✶°｡⋆｡ﾟ✶°｡⋆｡ﾟ✶°｡⋆\n\n＼💖 ぜ〜んぶまとめてスッキリ整理♡ 💖／\n\n✨ 完全無料！！\n✨ 登録不要！！\n✨ 面倒な操作ナシ！！\n✨ 削除率99.9％以上！？\n\n「消したいけど、なんとなく残してる……」\n\n「もう見たくないのに、捨てられない……」\n\nそんな時は――\n\n🦋 お片付け担当・アゲハにお任せ♡\n\n明るくて世話焼き。\nちょっぴりお節介なオネエのお片付け担当が、\n\nユーザーちゃんの\n「もういらない」 をお手伝いします♡\n\n╭──────────────╮\n　💗 捨てるのが苦手でも大丈夫 💗\n╰──────────────╯\n\n「いらないなら、捨てちゃえばいいじゃない♡」\n\n写真でも。\n履歴でも。\n昔の思い出でも。\n\nアゲハと一緒に、\n少しずつ綺麗にしていきましょう✨\n\n⋆｡ﾟ✶°｡⋆｡ﾟ✶°｡⋆｡ﾟ✶°｡⋆\n\n💖🦋 お片付け受付中 🦋💖\n\n✨ 黒歴史\n✨ 不要データ\n✨ 見たくないもの\n✨ 忘れてしまいたいもの\n\n＼アタシが綺麗にしてあげる♡／\n\n【🦋 謨ｴ逅�蟇ｾ雎｡】\n\n╰━━━━━━━ 🦋✨💖✨🦋 ━━━━━━━╯",
